// Medical Terminology Practice Test 3. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and using different terms from Practice Tests 1 and 2.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-3',
 event:'Medical Terminology',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'What does the suffix -cele mean?','Hernia or protrusion',['Cell or small unit','Swelling with fluid','Rupture or bursting'],'A','A cystocele is a protrusion of the bladder into the vaginal wall. Do not confuse -cele with -rrhexis (rupture).',EHR),
  q(WP,'Which suffix means “cutting into” or “incision”?','-tomy',['-ectomy','-stomy','-tripsy'],'B','-tomy means incision, -ectomy means removal, -stomy means creating an opening and -tripsy means crushing.',EHR),
  q(WP,'What does the suffix -megaly mean?','Enlargement',['Softening','Hardening','Narrowing'],'C','Cardiomegaly is enlargement of the heart; softening is -malacia, hardening is -sclerosis and narrowing is -stenosis.',EHR),
  q(WP,'What does the suffix -pathy mean?','Disease',['Feeling','Treatment','Suffering only from pain'],'D','Neuropathy is disease of the nerves. Note that -path- also appears in pathology, the study of disease.',EHR),
  q(WP,'What does the suffix -plegia mean?','Paralysis',['Weakness','Tremor','Spasm'],'A','Hemiplegia is paralysis of one side; -paresis means slight paralysis or weakness, as in hemiparesis.',EHR),
  q(WP,'What does the suffix -sclerosis mean?','Abnormal hardening',['Abnormal softening','Abnormal widening','Abnormal twisting'],'B','Arteriosclerosis is hardening of the arteries; scler/o can also refer to the white of the eye.',EHR),
  q(WP,'Which suffix means “the process of recording”?','-graphy',['-gram','-graph','-scopy'],'C','-graphy is the process, -gram is the record produced, -graph is the instrument and -scopy is visual examination.',EHR),
  q(WP,'What does the suffix -trophy mean?','Development or nourishment',['Treatment or healing','Turning or twisting','Attraction or affinity'],'D','Atrophy is wasting from lack of development; hypertrophy is enlargement from increased cell size.',EHR),
  q(WP,'Which prefix means “within”?','intra-',['inter-','infra-','extra-'],'A','Intra- means within (intravenous), inter- means between (intercostal), infra- means below and extra- means outside.',EHR),
  q(WP,'Which prefix means “against” or “opposite”?','contra-',['con-','co-','ad-'],'B','Contraindication is a reason not to give a treatment. Con- and co- mean together, and ad- means toward.',EHR),
  q(WP,'What does the prefix neo- mean?','New',['Nerve','Not','Near'],'C','A neoplasm is a new, abnormal growth of tissue; neur/o, not neo-, refers to nerves.',EHR),
  q(WP,'What does the prefix pan- mean?','All',['Many','Half','Around'],'D','Pancytopenia is a deficiency of all blood cell types. Many is poly-, half is hemi- and around is peri-.',EHR),
  q(WP,'What does the combining form cyan/o mean?','Blue',['Red','Yellow','White'],'A','Cyanosis is bluish skin from low oxygen. Red is erythr/o, yellow is xanth/o or jaund/o and white is leuk/o.',EHR),
  q(WP,'What does the combining form chondr/o refer to?','Cartilage',['Ligament','Bone marrow','Tendon'],'B','Chondromalacia is softening of cartilage. Tendon is ten/o or tendin/o, and bone marrow is myel/o.',EHR),
  q(WP,'What does the combining form aden/o refer to?','Gland',['Fat','Fluid','Nerve root'],'C','Adenoma is a benign glandular tumor. Fat is lip/o or adip/o, and nerve root is radicul/o.',EHR),
  q(WP,'What does the combining form cephal/o refer to?','Head',['Brain','Neck','Spine'],'D','Cephalalgia is a headache. Brain is encephal/o, neck is cervic/o and spine is spin/o or rachi/o.',EHR),
  q(WP,'What does the combining form hyster/o refer to?','Uterus',['Ovary','Bladder','Fallopian tube'],'A','Hysterectomy is removal of the uterus; metr/o and uter/o also refer to it. Ovary is oophor/o and fallopian tube is salping/o.',EHR),
  q(WP,'What does the combining form enter/o refer to?','Intestines, usually small',['Stomach','Esophagus','Large intestine only'],'B','Gastroenteritis involves the stomach and intestines. The large intestine is col/o, and the esophagus is esophag/o.',EHR),
  q(WP,'What does the combining form dacry/o refer to?','Tears',['Teeth','Fingers','Eyelashes'],'C','Dacryocystitis is inflammation of the tear sac. Teeth are dent/o or odont/o, and fingers are dactyl/o.',EHR),
  q(WP,'What does the combining form ot/o refer to?','Ear',['Eye','Mouth','Bone'],'D','Otitis media is middle ear inflammation. Eye is ophthalm/o or ocul/o, mouth is or/o or stomat/o and bone is oste/o.',EHR),
  q(WP,'What is the plural of diagnosis?','Diagnoses',['Diagnosises','Diagnosi','Diagnosae'],'A','Words ending in -is form plurals by changing -is to -es, as in diagnosis/diagnoses and metastasis/metastases.',EHR),
  q(WP,'What is the plural of vertebra?','Vertebrae',['Vertebras','Vertebri','Vertebrata'],'B','Words ending in -a form plurals by changing -a to -ae, as in vertebra/vertebrae and bursa/bursae.',EHR),
  q(WP,'What does the combining form pneum/o mean?','Lung or air',['Rib or chest','Heart or blood','Nose or smell'],'C','Pneumonia is lung inflammation and pneumothorax is air in the chest. Pulmon/o also means lung.',EHR),
  q(BODY,'Which body cavity contains the heart and lungs?','Thoracic cavity',['Abdominal cavity','Pelvic cavity','Cranial cavity'],'D','The thoracic cavity is separated from the abdominopelvic cavity by the diaphragm and holds the heart and lungs.',EHR),
  q(BODY,'A patient lies face down for a procedure. Which term describes this position?','Prone',['Supine','Lateral','Fowler’s'],'A','Prone is face down; supine is face up. Fowler’s is semi-sitting, and lateral is lying on the side.',EHR),
  q(SKEL,'What is osteoporosis?','Loss of bone density',['Infection of the bone and marrow','Inflammation of the bone and joints','Abnormal growth of cartilage cells'],'B','Oste/o (bone) + por/o (pore) + -osis. Infection of bone is osteomyelitis, and joint inflammation is arthritis.',EHR),
  q(SKEL,'Which term describes an abnormal outward curvature of the upper spine, or “humpback”?','Kyphosis',['Lordosis','Scoliosis','Spondylosis'],'C','Kyphosis is an exaggerated thoracic curve; lordosis is lumbar swayback and scoliosis is a sideways curve.',EHR),
  q(SKEL,'What is the common name for the patella?','Kneecap',['Shinbone','Collarbone','Shoulder blade'],'D','The patella is the kneecap; the shinbone is the tibia, the collarbone is the clavicle and the shoulder blade is the scapula.',EHR),
  q(MUS,'What does myalgia mean?','Muscle pain',['Muscle tear','Muscle tumor','Muscle cramp'],'A','My/o (muscle) + -algia (pain). A muscle tumor is a myoma; a cramp or spasm is a myospasm.',EHR),
  q(MUS,'Which term describes wasting away of muscle from disuse?','Atrophy',['Hypertrophy','Dystrophy','Myoclonus'],'B','Atrophy is a decrease in size; hypertrophy is enlargement, dystrophy is faulty development and myoclonus is muscle jerking.',EHR),
  q(RESP,'What does apnea mean?','Absence of breathing',['Slow breathing','Painful breathing','Breathing only when upright'],'C','A- (without) + -pnea (breathing). Slow breathing is bradypnea, and breathing only upright is orthopnea.',EHR),
  q(RESP,'What does rhinorrhea mean?','Runny nose',['Nosebleed','Stuffy nose','Nasal polyp'],'D','Rhin/o (nose) + -rrhea (flow or discharge). A nosebleed is epistaxis.',EHR),
  q(RESP,'What is pleurisy?','Inflammation of the pleura',['Pus in the pleural space','Air in the pleural space','Blood in the pleural space'],'A','Pleurisy (pleuritis) causes sharp chest pain with breathing. Pus is empyema, air is pneumothorax and blood is hemothorax.',EHR),
  q(DIG,'What does hepatitis mean?','Inflammation of the liver',['Enlargement of the liver','Tumor of the liver','Removal of part of the liver'],'B','Hepat/o (liver) + -itis (inflammation). Enlargement is hepatomegaly, and a tumor is a hepatoma.',EHR),
  q(DIG,'Which term means inflammation of the stomach and intestines?','Gastroenteritis',['Gastritis','Colitis','Esophagitis'],'C','Gastr/o (stomach) + enter/o (intestine) + -itis. It often causes vomiting and diarrhea.',EHR),
  q(CV,'What is hypertension?','Persistently high blood pressure',['Persistently low blood pressure','A fast, irregular heartbeat','A narrowed heart valve'],'D','Hypertension is elevated arterial pressure; hypotension is low blood pressure.',EHR),
  q(CV,'What is thrombophlebitis?','Vein inflammation with a clot',['Artery hardening with plaque','Heart muscle inflammation','A ruptured blood vessel'],'A','Thromb/o (clot) + phleb/o (vein) + -itis. It often occurs in the leg veins.',EHR),
  q(CV,'What does splenomegaly mean?','Enlargement of the spleen',['Removal of the spleen','Rupture of the spleen','Pain in the spleen'],'B','Splen/o (spleen) + -megaly (enlargement). Removal is splenectomy and rupture is splenorrhexis.',EHR),
  q(NERV,'What does neuralgia mean?','Nerve pain',['Nerve inflammation','Nerve tumor','Nerve repair'],'C','Neur/o (nerve) + -algia (pain). Inflammation is neuritis, a tumor is a neuroma and repair is neuroplasty.',EHR),
  q(NERV,'What is otitis media?','Middle ear inflammation',['Outer ear inflammation','Inner ear inflammation','Eardrum rupture'],'D','Otitis media is common in children; otitis externa (“swimmer’s ear”) affects the outer ear canal.',EHR),
  q(NERV,'What is conjunctivitis?','Inflamed eye lining (pinkeye)',['Clouding of the lens','Increased eye pressure','Detachment of the retina'],'A','Conjunctivitis, or pinkeye, inflames the conjunctiva. Lens clouding is cataract; high pressure is glaucoma.',EHR),
  q(ENDO,'What does hypoglycemia mean?','Low blood sugar',['High blood sugar','Low blood calcium','High blood sodium'],'B','Hypo- (below) + glyc/o (sugar) + -emia (blood condition). It causes shakiness, sweating and confusion.',EHR),
  q(ENDO,'What is a goiter?','An enlarged thyroid gland',['An enlarged adrenal gland','An underactive pituitary gland','A tumor of the pancreas'],'C','A goiter may occur with iodine deficiency or thyroid disease and appears as swelling in the front of the neck.',EHR),
  q(REPRO,'What is a hysterectomy?','Surgical removal of the uterus',['Surgical removal of an ovary','Incision into the uterus','Visual examination of the uterus'],'D','Hyster/o (uterus) + -ectomy. Removing an ovary is oophorectomy, and viewing the uterus is hysteroscopy.',EHR),
  q(REPRO,'What is mastitis?','Inflammation of the breast',['Inflammation of the uterus','Tumor of the breast','Pain in the breast'],'A','Mast/o and mamm/o refer to the breast. Breast pain is mastalgia or mastodynia.',EHR),
  q(INTEG,'What does pruritus mean?','Itching',['Redness','Scaling','Blistering'],'B','Pruritus is a symptom of many skin conditions. Redness is erythema, and a blister is a vesicle or bulla.',EHR),
  q(INTEG,'What is cellulitis?','A spreading skin infection',['A benign tumor of fat cells','A burn of the outer skin layer','A loss of skin color in patches'],'C','Cellulitis is a bacterial infection of the skin and subcutaneous tissue. Loss of skin color in patches is vitiligo.',EHR),
  q(URIN,'What is cystitis?','Inflamed urinary bladder',['Inflammation of the kidney','Stones in the bladder','Narrowing of the urethra'],'D','Cyst/o (bladder) + -itis. Kidney inflammation is nephritis, and bladder stones are cystolithiasis.',EHR),
  q(URIN,'What does dysuria mean?','Painful urination',['Frequent urination','Absence of urine','Blood in the urine'],'A','Dys- (painful, difficult) + -uria. Absence of urine is anuria, and blood in urine is hematuria.',EHR),
  q(URIN,'What is nephrolithiasis?','Kidney stones',['Kidney failure','Kidney infection','Kidney enlargement'],'B','Nephr/o (kidney) + lith/o (stone) + -iasis (condition). Kidney infection of the pelvis is pyelonephritis.',EHR)
 ],5202)
};
